import { HINUNANGAN_BARANGAYS } from './barangays';

export interface BarangayGeoFeature {
  type: 'Feature';
  id: string;
  properties: {
    id: string;
    name: string;
    code: string;
    isUrban: boolean;
    latitude: number;
    longitude: number;
    focalPersonName: string;
    contactNumber: string;
    defaultRiskLevel: 'green' | 'yellow' | 'red';
    defaultSwineCount: number;
    defaultReadyToSellCount: number;
    areaHectares: number;
    perimeterKm: number;
  };
  geometry: {
    type: 'Polygon';
    coordinates: number[][][]; // [ [ [lng, lat], [lng, lat], ... ] ]
  };
}

export interface HinunanganGeoJSON {
  type: 'FeatureCollection';
  features: BarangayGeoFeature[];
}

